SELECT
    COUNT(*)::bigint AS "추적 이벤트"
FROM audit_auditlog
WHERE
    $__timeFilter(occurred_at)

    AND (
        ${tracking_code:sqlstring} = ''
        OR (
            'ERR-' ||
            UPPER(
                SUBSTRING(
                    REPLACE(
                        request_id::text,
                        '-',
                        ''
                    )
                    FROM 1 FOR 16
                )
            )
        ) = UPPER(
            ${tracking_code:sqlstring}
        )
    )

    AND (
        ${request_id:sqlstring} = ''
        OR request_id::text =
            ${request_id:sqlstring}
    )

