list.query:
SELECT
    request_id::text
        AS __text,

    request_id::text
        AS __value

FROM audit_auditlog

WHERE
    request_id IS NOT NULL

    AND
    TRIM(
        BOTH FROM ${request_id:sqlstring}
    ) <> ''

    AND
    (
    (
        UPPER(
            TRIM(
                BOTH FROM ${request_id:sqlstring}
            )
        ) LIKE 'ERR-%'

        AND

        LEFT(
            REPLACE(
                UPPER(
                    request_id::text
                ),
                '-',
                ''
            ),
            16
        )
        =
        LEFT(
            REGEXP_REPLACE(
                UPPER(
                    REPLACE(
                        TRIM(
                            BOTH FROM ${request_id:sqlstring}
                        ),
                        'ERR-',
                        ''
                    )
                ),
                '[^0-9A-F]',
                '',
                'g'
            ),
            16
        )
    )

    OR

    (
        UPPER(
            TRIM(
                BOTH FROM ${request_id:sqlstring}
            )
        ) NOT LIKE 'ERR-%'

        AND

        REPLACE(
            UPPER(
                request_id::text
            ),
            '-',
            ''
        )
        =
        REGEXP_REPLACE(
            UPPER(
                TRIM(
                    BOTH FROM ${request_id:sqlstring}
                )
            ),
            '[^0-9A-F]',
            '',
            'g'
        )
    )
)

GROUP BY
    request_id

ORDER BY
    MAX(occurred_at) DESC

LIMIT 1

